    function quoteBestExactInput(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint8 candidateBitmap
    ) external view returns (
        address selectedPool,
        uint256 selectedFeeBps,
        bool zeroForOne,
        uint256 amountOut
    );

    function swapBestExactInput(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        uint8 candidateBitmap,
        address recipient,
        uint64 deadline
    ) external returns (
        address selectedPool,
        uint256 selectedFeeBps,
        uint256 amountOut
    );
}

